/**
 * @summary Capture a "Request a demo" / trial-request lead
 */
export const createLeadBodyWebsiteMax = 200;

export const createLeadBodyNameMax = 200;

export const createLeadBodyEmailMin = 3;
export const createLeadBodyEmailMax = 320;

export const createLeadBodyOrganizationMax = 200;

export const createLeadBodyCityMax = 120;

export const createLeadBodyRoleMax = 200;

export const createLeadBodyMessageMax = 4000;

export const createLeadBodyProductInterestMax = 80;

export const CreateLeadBody = zod.object({
  website: zod
    .string()
    .max(createLeadBodyWebsiteMax)
    .optional()
    .describe("Honeypot — must be empty."),
  name: zod.string().min(1).max(createLeadBodyNameMax),
  email: zod
    .string()
    .email()
    .min(createLeadBodyEmailMin)
    .max(createLeadBodyEmailMax),
  organization: zod
    .string()
    .min(1)
    .max(createLeadBodyOrganizationMax)
    .describe("City, agency, firm, or company name."),
  city: zod
    .string()
    .min(1)
    .max(createLeadBodyCityMax)
    .describe(
      "City the lead represents (often equals organization for municipal leads).",
    ),
  role: zod.string().max(createLeadBodyRoleMax).optional(),
  message: zod.string().max(createLeadBodyMessageMax).optional(),
  productInterest: zod
    .string()
    .max(createLeadBodyProductInterestMax)
    .optional()
    .describe('Free-form tag — typically a tier name or \"tis\".'),
  source: zod
    .enum(["pricing_page", "for_firms_page", "trial_request", "other"])
    .optional(),
});
